import{_ as e,o as t,c as i,a2 as r}from"./chunks/framework.CDpkVv68.js";const m=JSON.parse('{"title":"Familiarity & Practice","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/characters/familiarity.md","filePath":"en/guide/characters/familiarity.md"}'),n={name:"en/guide/characters/familiarity.md"};function l(s,a,c,o,d,h){return t(),i("div",null,[...a[0]||(a[0]=[r('<h1 id="familiarity-practice" tabindex="-1">Familiarity &amp; Practice <a class="header-anchor" href="#familiarity-practice" aria-label="Permalink to &quot;Familiarity &amp; Practice&quot;">​</a></h1><p><strong>Status:</strong> Proposed · Availability not established.</p><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Permalink to &quot;TL;DR&quot;">​</a></h2><ul><li>Familiarity tracks fluency with a learned action, without consuming extra skillcap.</li><li>Learned, Practiced and Mastered describe execution quality, not new skills.</li><li>Active play can require maintenance; calendar absence does not erase knowledge or punish fluency.</li></ul><p><span id="familiarity-and-practice"></span><span id="at-a-glance"></span><span id="maintenance-test"></span><span id="training-and-preparation"></span></p><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Element</th><th>Player meaning</th></tr></thead><tbody><tr><td>Learned</td><td>The action remains known even when practice is low.</td></tr><tr><td>Practiced</td><td>Regular practice supports standard execution.</td></tr><tr><td>Mastered</td><td>Refined execution may improve efficiency, consistency or timing tolerance; it does not guarantee success.</td></tr></tbody></table><h2 id="compared-with-classic-uo" tabindex="-1">Compared with classic UO <a class="header-anchor" href="#compared-with-classic-uo" aria-label="Permalink to &quot;Compared with classic UO&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Classic UO</th><th>Syrolands direction</th></tr></thead><tbody><tr><td>UO Skill Masteries are a separate, era-dependent ability system.</td><td>Familiarity describes practice with individual learned actions; it is not that UO system.</td></tr><tr><td>General skill is a familiar measure of proficiency.</td><td>Keep general skill separate from action fluency and the choices prepared for use.</td></tr></tbody></table><p>UO rules vary by era and shard. <a href="https://uo.com/wiki/ultima-online-wiki/skills/skill-masteries/" target="_blank" rel="noreferrer">Official UO: Skill Masteries</a>.</p><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><p>A returning swordsman keeps the techniques they learned. During active play, neglected fluency may fall toward Learned, while purposeful practice helps maintain it.</p><h2 id="progression-trade-offs" tabindex="-1">Progression / trade-offs <a class="header-anchor" href="#progression-trade-offs" aria-label="Permalink to &quot;Progression / trade-offs&quot;">​</a></h2><p>Training facilities may maintain fluency efficiently without replacing discovery or becoming the best core-skill grind. Exact gain and maintenance rules remain open; martial preparation and magical memory do not share a settled capacity formula.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><p><a href="/Syrolands-Public/en/guide/characters/techniques.html">Techniques</a> · <a href="/Syrolands-Public/en/guide/magic/memory-and-familiarity.html">Spell Memory</a> · <a href="/Syrolands-Public/en/guide/combat/special-attacks.html">Special Attacks</a></p><h2 id="full-design-specification" tabindex="-1">Full design specification <a class="header-anchor" href="#full-design-specification" aria-label="Permalink to &quot;Full design specification&quot;">​</a></h2><p>Read the <a href="/Syrolands-Public/en/game-design/characters/familiarity.html">Familiarity &amp; Practice</a> design specification.</p>',18)])])}const u=e(n,[["render",l]]);export{m as __pageData,u as default};
